G=/home/user/.config/gtk-3.0/gtk.css; W=/usr/share/backgrounds/my-wall.jpg; R() { cp -p $G.bak-home3 $G; chown user:user $G; systemctl restart pixel-phosh; echo ROLLED-BACK; }; [ -f $G ] || { echo FAIL-no-gtk-css; exit 1; }; [ -r $W ] || { echo FAIL-no-wallpaper; exit 1; }; [ -e $G.bak-home3 ] || cp -p $G $G.bak-home3 || { echo FAIL-backup; exit 1; }; grep -vE "phosh-home|phosh-overview|phosh-app-grid" $G > $G.new; printf "%s\n" "phosh-home { background-color: #000000; background-image: url(\"$W\"); background-size: cover; background-position: center; background-repeat: no-repeat; }" "phosh-home > box > widget { background-color: #000000; background-image: none; }" "phosh-overview, phosh-app-grid { background: none; }" >> $G.new; [ $(grep -c "^phosh-home {" $G.new) = 1 ] || { echo FAIL-write; exit 1; }; mv $G.new $G; chown user:user $G; chmod 644 $G; T=$(date "+%Y-%m-%d %H:%M:%S"); systemctl restart pixel-phosh; for i in $(seq 1 30); do sleep 1; pgrep -x phosh > /dev/null && break; done; sleep 8; pgrep -x phosh > /dev/null || { echo FAIL-phosh-not-running; R; exit 1; }; N=$(journalctl -b --since "$T" --no-pager 2>/dev/null | grep -ci "theme parsing error"); [ "$N" = 0 ] || { echo FAIL-css-errors-$N; R; exit 1; }; echo HOME-DONE
